session_start();require __DIR__ . '/../../config/db_connection.php';if(!isset($_SESSION['admin_id'])){header('Location:/Ordering/app/admin/admin_login.php');exit;}function auditAdmin($c,$id,$text){$s=$c->prepare('INSERT INTO admin_audit_log(admin_id,action_text) VALUES(?,?)');$s->bind_param('is',$id,$text);$s->execute();$s->close();}$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['seller_id']??0);$status=$_POST['status']??'';if($id&&in_array($status,['approved','rejected','suspended'],true)){$s=$conn->prepare('UPDATE sellers SET approval_status=? WHERE id=?');$s->bind_param('si',$status,$id);$s->execute();$s->close();auditAdmin($conn,$_SESSION['admin_id'],"Set seller #$id status to $status");$message='Seller access updated.';}}
$counts=[];foreach(['Students'=>'students','Sellers'=>'sellers','Orders'=>'orders'] as $label=>$table)$counts[$label]=(int)$conn->query("SELECT COUNT(*) c FROM $table")->fetch_assoc()['c'];$revenue=$conn->query("SELECT COALESCE(SUM(total),0) r FROM orders WHERE LOWER(status)='completed'")->fetch_assoc()['r'];$r=$conn->query("SELECT s.id,s.full_name,s.email,s.contact,s.approval_status,s.created_at,COALESCE(c.canteen_name,'No canteen profile yet') canteen_name FROM sellers s LEFT JOIN canteens c ON c.seller_id=s.id ORDER BY s.created_at DESC");$groups=['pending'=>[],'approved'=>[],'rejected'=>[],'suspended'=>[]];while($seller=$r->fetch_assoc())$groups[$seller['approval_status']][]=$seller;
?><!doctype html><html><head><base href="/Ordering/"><meta charset="utf-8"><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700&family=Poppins:wght@400;600&display=swap" rel="stylesheet"><style>:root{--blue:#2563eb;--muted:#64748b}*{box-sizing:border-box}body{margin:0;padding:24px;font:14px Poppins,sans-serif;background:#f1f5f9;color:#0f172a}.top,.card,.stat{background:#fff;border-radius:12px;box-shadow:0 2px 10px #0000000d}.top{padding:18px 22px;margin-bottom:18px}.top h1{margin:0;font:700 21px Montserrat}.top p{margin:5px 0;color:var(--muted);font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.stat{padding:17px}.stat span{color:var(--muted);font-size:12px}.stat b{display:block;font:700 23px Montserrat;margin-top:6px}.card{padding:18px;overflow:auto}.tabs{display:flex;gap:8px;margin:14px 0}.tabs button{border:0;border-radius:8px;padding:9px 13px;background:#e2e8f0;font-weight:600;cursor:pointer;text-transform:capitalize}.tabs button.active{background:var(--blue);color:#fff}.panel{display:none}.panel.active{display:block}table{width:100%;min-width:780px;border-collapse:collapse}th,td{text-align:left;padding:11px 8px;border-bottom:1px solid #e2e8f0;font-size:13px}th{color:var(--muted);font-size:12px}.pill{padding:4px 8px;border-radius:20px;background:#e2e8f0;text-transform:capitalize;font-size:12px}.canteen{color:#1d4ed8;font-weight:600}.actions{display:flex;gap:6px}.actions button{border:0;border-radius:7px;padding:7px 10px;color:#fff;font-weight:600;cursor:pointer}.approve{background:#16a34a}.suspend{background:#b45309}.reject{background:#dc2626}.notice{background:#dcfce7;color:#166534;padding:10px;border-radius:8px;margin-bottom:12px}.empty{color:var(--muted);padding:20px}@media(max-width:780px){.stats{grid-template-columns:repeat(2,1fr)}}</style></head><body><section class="top"><h1>Overview & Canteen Approvals</h1><p>Review seller requests together with their associated canteen profile.</p></section><?php if($message):?><div class="notice"><?=$message?></div><?php endif?><section class="stats"><?php foreach($counts as $name=>$value):?><article class="stat"><span><?=$name?></span><b><?=$value?></b></article><?php endforeach?><article class="stat"><span>Completed Revenue</span><b>PHP <?=number_format($revenue,2)?></b></article></section><section class="card"><h2 style="font:700 17px Montserrat;margin:0">Seller & canteen access</h2><div class="tabs"><?php foreach($groups as $key=>$list):?><button class="<?=$key==='pending'?'active':''?>" data-tab="<?=$key?>"><?=ucfirst($key)?> (<?=count($list)?>)</button><?php endforeach?></div><?php foreach($groups as $key=>$list):?><div class="panel <?=$key==='pending'?'active':''?>" id="<?=$key?>"><?php if(!$list):?><p class="empty">No <?=htmlspecialchars($key)?> seller accounts.</p><?php else:?><table><thead><tr><th>Seller</th><th>Canteen</th><th>Contact</th><th>Applied</th><th>Actions</th></tr></thead><tbody><?php foreach($list as $seller):?><tr><td><b><?=htmlspecialchars($seller['full_name'])?></b><br><small><?=htmlspecialchars($seller['email'])?></small></td><td class="canteen"><?=htmlspecialchars($seller['canteen_name'])?></td><td><?=htmlspecialchars($seller['contact'])?></td><td><?=htmlspecialchars($seller['created_at'])?></td><td><form class="actions" method="post"><input type="hidden" name="seller_id" value="<?=$seller['id']?>"><button class="approve" name="status" value="approved">Approve</button><button class="suspend" name="status" value="suspended">Suspend</button><button class="reject" name="status" value="rejected">Reject</button></form></td></tr><?php endforeach?></tbody></table><?php endif?></div><?php endforeach?></section><script>document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active');});</script></body></html>
